schema:
entity Secret @allow(read: viewer.role == "admin") { id: ID code: String }
entity Note { id: ID title: String secret: Secret? mustHave: Secret owner: String @allow(read: viewer.role == "admin") sometimes: String? @partial @allow(read: viewer.role == "admin") }
entity Box { id: ID items: [Secret] maybe: [Secret?] }
query note(id: ID): Note?
query box(id: ID): Box?
query boxWithGap(id: ID): Box?
query adminOnly(id: ID): Note? @allow(read: viewer.role == "admin")
